using System; using System.Runtime.Remoting; using System.Runtime.Remoting.Channels; using System.Runtime.Remoting.Channels.Tcp;
namespace Server { internal class Program { static void Main(string[] args) { try { TcpChannel channel=new TcpChannel(1069); ChannelServices.RegisterChannel(channel,false); RemotingConfiguration.RegisterWellKnownServiceType(typeof(RemoteOperation),"RemoteOperation",WellKnownObjectMode.Singleton); Console.WriteLine("Serveur demarre: TCP 1069 / RemoteOperation"); Console.ReadLine(); } catch(Exception ex) { Console.WriteLine("Erreur: "+ex.Message); Console.ReadLine(); } } } }
